import { useEffect, useState } from "react";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  ArcElement,
  Tooltip,
  Legend
} from "chart.js";
import { Bar, Pie } from "react-chartjs-2";
import "../../styles/admin-ui.css";

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  ArcElement,
  Tooltip,
  Legend
);

export default function Reports() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch("http://127.0.0.1:8000/api/orders/")
      .then(res => res.json())
      .then(data => {
        setOrders(data);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, []);

  if (loading) return <div className="reports-loading">Loading reports…</div>;
  if (!orders.length) return <div className="reports-empty">No sales data available</div>;

  /* ---------- Order status summary ---------- */
  const statusCount = {};
  orders.forEach(o => {
    statusCount[o.status] = (statusCount[o.status] || 0) + 1;
  });

  const pieData = {
    labels: Object.keys(statusCount),
    datasets: [
      {
        data: Object.values(statusCount),
        backgroundColor: ["#fbbf24", "#22c55e", "#3b82f6"]
      }
    ]
  };

  /* ---------- Item sales aggregation ---------- */
  const itemSales = {};
  orders.forEach(o => {
    o.items.forEach(i => {
      itemSales[i.name] = (itemSales[i.name] || 0) + i.quantity;
    });
  });

  const itemSalesData = {
    labels: Object.keys(itemSales),
    datasets: [
      {
        label: "Items Sold",
        data: Object.values(itemSales),
        backgroundColor: "#2563eb"
      }
    ]
  };

  return (
    <div className="reports-wrapper">
      <h3 className="reports-title">Sales Report</h3>
      <p className="reports-subtitle">Live performance overview</p>

      <div className="reports-grid">
        {/* Order Status */}
        <div className="reports-chart-card">
          <h4>Orders by Status</h4>
          <div className="reports-chart-wrapper">
            <Pie data={pieData} />
          </div>
        </div>

        {/* Item sales */}
        <div className="reports-chart-card">
          <h4>Item Sales (Quantity)</h4>
          <div className="reports-chart-wrapper">
            <Bar
              data={itemSalesData}
              options={{
                responsive: true,
                plugins: { legend: { display: false } }
              }}
            />
          </div>
        </div>
      </div>
    </div>
  );
}
